package main

import (
	"bytes"
	"database/sql"
	"errors"
	"html/template"
	"log"
	"net/http"
)

var tmpl = template.Must(template.ParseGlob("templates/*.html")) // layout.html has the <nav> with <a href="/">; 404.html, 410.html, 500.html, 503.html extend it

type page struct {
	Nonce string
	Data  any
}

// render writes a full page with an explicit status, decided before the body is written.
func render(w http.ResponseWriter, r *http.Request, status int, name string, data any) {
	var buf bytes.Buffer
	if err := tmpl.ExecuteTemplate(&buf, name, page{Nonce: nonceFrom(r.Context()), Data: data}); err != nil {
		log.Printf("template %s: %v", name, err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	if status >= 400 && w.Header().Get("X-Robots-Tag") == "" { // 404/410/5xx pages are not indexable; keep "noindex, nofollow" if the middleware already set it
		w.Header().Set("X-Robots-Tag", "noindex")
	}
	w.WriteHeader(status)
	_, _ = buf.WriteTo(w)
}

var retired = map[string]bool{"/old-product": true, "/2019-sale": true} // removed, no successor

func registerRoutes(mux *http.ServeMux, store *Store) {
	mux.HandleFunc("GET /{$}", func(w http.ResponseWriter, r *http.Request) { render(w, r, http.StatusOK, "home.html", nil) })

	mux.HandleFunc("GET /blog/{slug}", func(w http.ResponseWriter, r *http.Request) {
		post, err := store.Post(r.Context(), r.PathValue("slug"))
		switch {
		case errors.Is(err, sql.ErrNoRows):
			render(w, r, http.StatusNotFound, "404.html", nil) // RTE-005/006: unknown param -> 404 before any output
		case err != nil:
			log.Printf("post lookup: %v", err)
			w.Header().Set("Retry-After", "30")
			render(w, r, http.StatusServiceUnavailable, "503.html", nil) // RTE-007: dependency failure -> 5xx
		default:
			render(w, r, http.StatusOK, "post.html", post)
		}
	})

	// Everything no other pattern matched: RTE-004 unknown URL -> 404, retired -> 410.
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if retired[r.URL.Path] {
			render(w, r, http.StatusGone, "410.html", nil)
			return
		}
		render(w, r, http.StatusNotFound, "404.html", nil)
	})
}

func recoverPanics(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				log.Printf("panic: %v", rec) // details stay in the server log
				render(w, r, http.StatusInternalServerError, "500.html", nil)
			}
		}()
		next.ServeHTTP(w, r)
	})
}
