package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"net/mail"
	"os"
	"strings"
	"sync"
	"time"

	"golang.org/x/time/rate"
)

var (
	mu       sync.Mutex
	limiters = map[string]*rate.Limiter{} // grow-only here: evict idle entries in production
	client   = &http.Client{Timeout: 8 * time.Second}
)

func allow(ip string) bool { // SEC-054: 5 per 10 minutes per client, then 429
	mu.Lock()
	defer mu.Unlock()
	l, ok := limiters[ip]
	if !ok {
		l = rate.NewLimiter(rate.Every(2*time.Minute), 5)
		limiters[ip] = l
	}
	return l.Allow()
}

func contactForm(w http.ResponseWriter, r *http.Request) {
	if r.URL.Query().Get("sent") == "1" {
		render(w, r, http.StatusOK, "contact-sent.html", nil)
		return
	}
	render(w, r, http.StatusOK, "contact.html", nil)
}

func contactSubmit(w http.ResponseWriter, r *http.Request) {
	ip, _, _ := net.SplitHostPort(r.RemoteAddr)
	if !allow(ip) {
		w.Header().Set("Retry-After", "600")
		http.Error(w, "too many requests", http.StatusTooManyRequests)
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, 64<<10)
	if err := r.ParseForm(); err != nil {
		http.Error(w, "invalid form", http.StatusBadRequest)
		return
	}
	if r.PostForm.Get("website") != "" { // honeypot (SEC-055) filled: look successful, do nothing
		http.Redirect(w, r, "/contact?sent=1", http.StatusSeeOther)
		return
	}
	name, email, msg := strings.TrimSpace(r.PostForm.Get("name")), strings.TrimSpace(r.PostForm.Get("email")), strings.TrimSpace(r.PostForm.Get("message"))
	if _, err := mail.ParseAddress(email); err != nil || name == "" || len(name) > 100 || len(email) > 254 || msg == "" || len(msg) > 5000 {
		http.Error(w, "invalid form", http.StatusBadRequest)
		return
	}

	payload, _ := json.Marshal(map[string]string{"name": name, "email": email, "message": msg})
	req, err := http.NewRequestWithContext(r.Context(), http.MethodPost, os.Getenv("FORM_WEBHOOK_URL"), bytes.NewReader(payload)) // the real destination (UX-001)
	if err == nil {
		req.Header.Set("Content-Type", "application/json")
		var resp *http.Response
		if resp, err = client.Do(req); err == nil {
			defer resp.Body.Close()
			if resp.StatusCode/100 != 2 {
				err = fmt.Errorf("webhook status %d", resp.StatusCode)
			}
		}
	}
	if err != nil {
		render(w, r, http.StatusBadGateway, "502.html", nil) // RES-008: delivery failed -> 5xx page, never the success state
		return
	}
	http.Redirect(w, r, "/contact?sent=1", http.StatusSeeOther)
}
