Go net/http (Go 1.22+ ServeMux; the form-handler recipe uses Go 1.25's http.CrossOriginProtection). One middleware sets a per-request nonce CSP and the other headers on every response; templates stamp the nonce on their <script> and <style> tags. Content-hashed files under /assets/ (name contains .<8+ hex>.) are served immutable; everything else, HTML and unhashed files, revalidates. Chain the middleware as securityHeaders(recoverPanics(mux)) so every response, including error pages and 403s, gets the headers and the request carries the nonce.
### file: middleware.go
package main

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"net/http"
	"os"
	"regexp"
	"strings"
)

var hashedName = regexp.MustCompile(`[.-][a-f0-9]{8,}\.`) // same test PRF-008 uses for "content-hashed"

type nonceKey struct{}

// nonceFrom returns the CSP nonce of the current request; pass it to templates as {{.Nonce}}.
func nonceFrom(ctx context.Context) string {
	n, _ := ctx.Value(nonceKey{}).(string)
	return n
}

func securityHeaders(next http.Handler) http.Handler {
	nonProduction := os.Getenv("DEPLOY_ENV") != "production"
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b := make([]byte, 16)
		if _, err := rand.Read(b); err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		nonce := base64.StdEncoding.EncodeToString(b) // fresh per response
		h := w.Header()
		h.Set("Content-Security-Policy", strings.Join([]string{
			"default-src 'self'",
			"script-src 'self' 'nonce-" + nonce + "' 'strict-dynamic'", // SEC-075: nonce + strict-dynamic, no wildcard
			"style-src 'self' 'nonce-" + nonce + "'",
			"img-src 'self' data:",
			"font-src 'self'",
			"connect-src 'self'", // with analytics add: https://www.google-analytics.com https://*.google-analytics.com https://*.analytics.google.com
			"object-src 'none'",  // SEC-075(d)
			"base-uri 'self'",    // SEC-075(e)
			"form-action 'self'",
			"frame-ancestors 'none'", // SEC-010
			"upgrade-insecure-requests",
		}, "; "))
		h.Set("X-Content-Type-Options", "nosniff")
		h.Set("Referrer-Policy", "strict-origin-when-cross-origin")
		h.Set("Permissions-Policy", "camera=(), microphone=(), geolocation=()")
		if r.TLS != nil || r.Header.Get("X-Forwarded-Proto") == "https" { // HSTS only over HTTPS (RFC 6797); trust the header only behind your own proxy
			h.Set("Strict-Transport-Security", "max-age=63072000; includeSubDomains")
		}
		if nonProduction {
			h.Set("X-Robots-Tag", "noindex, nofollow") // IDX-005
		}
		if strings.HasPrefix(r.URL.Path, "/assets/") && hashedName.MatchString(r.URL.Path) { // PRF-008: only content-hashed names (app.3f9c1b7a.js); other files revalidate
			h.Set("Cache-Control", "public, max-age=31536000, immutable")
		} else {
			h.Set("Cache-Control", "public, max-age=0, must-revalidate")
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), nonceKey{}, nonce)))
	})
}
