Go net/http (Go 1.22+). Mode comes from DEPLOY_ENV only (`production` is the one production value), read at request time. Non-production: Disallow: /, no Sitemap line, /sitemap.xml answers 404, and X-Robots-Tag: noindex, nofollow on every response (set in the securityHeaders middleware of the headers recipe). Above 50,000 URLs split the file and serve a sitemap index. Remove any static robots.txt from ./static so it cannot shadow this handler.
### file: seo.go
package main

import (
	"encoding/xml"
	"fmt"
	"net/http"
	"os"
	"strings"
)

func isProduction() bool { return os.Getenv("DEPLOY_ENV") == "production" }

func siteURL() string { // canonical origin without trailing slash
	u := os.Getenv("SITE_URL")
	if u == "" {
		u = "https://example.com"
	}
	return strings.TrimRight(u, "/")
}

func robotsHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	if !isProduction() {
		fmt.Fprint(w, "User-agent: *\nDisallow: /\n") // IDX-005
		return
	}
	// IDX-004: only app/API paths are disallowed; CSS, JS and images stay crawlable
	fmt.Fprintf(w, "User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /account/\n\nSitemap: %s/sitemap.xml\n", siteURL())
}

type urlEntry struct {
	Loc string `xml:"loc"`
}
type urlSet struct {
	XMLName xml.Name   `xml:"urlset"`
	Xmlns   string     `xml:"xmlns,attr"`
	URLs    []urlEntry `xml:"url"`
}

// indexablePaths returns only pages that answer 200, are self-canonical and not noindex (IDX-001).
func sitemapHandler(indexablePaths func(r *http.Request) ([]string, error)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if !isProduction() {
			render(w, r, http.StatusNotFound, "404.html", nil) // IDX-005: no sitemap outside production
			return
		}
		paths, err := indexablePaths(r)
		if err != nil {
			http.Error(w, "service unavailable", http.StatusServiceUnavailable)
			return
		}
		set := urlSet{Xmlns: "http://www.sitemaps.org/schemas/sitemap/0.9"}
		for _, p := range paths {
			set.URLs = append(set.URLs, urlEntry{Loc: siteURL() + p}) // same canonical form as the <link rel="canonical"> tags
		}
		w.Header().Set("Content-Type", "application/xml; charset=utf-8") // encoding/xml escapes the values
		fmt.Fprint(w, xml.Header)
		_ = xml.NewEncoder(w).Encode(set)
	}
}
